	var bw int32 = 0
	var b0 int32 = ax0
	var b1 int32 = ax0
	var k int32 = s
	for k < e {
		var ix int32 = port.CellsAt(io, k)
		var x0 int32 = port.CellsAt(it, ix*itStride)
		var x1 int32 = port.CellsAt(it, (ix*itStride)+1)
		if (x0 < ax1) && (x1 > ax0) {
			if (lcMin(x0, ax1) - lo) > bw {
				bw = lcMin(x0, ax1) - lo
				b0 = lo
				b1 = lcMin(x0, ax1)
			}
			lo = lcMax(lo, x1)
		}
		k += 1
	}
	if (ax1 - lo) > bw {
		bw = ax1 - lo
		b0 = lo
		b1 = ax1
	}
	port.CellsSet(tm, 0, b0)
	port.CellsSet(tm, 1, b1)
	return bw
